9	/**
10	 * Collects shape problems of an untrusted JSON body. It checks types only;
11	 * business invariants (ranges, limits, supported values) belong to the core.
12	 */
13	export class InputReader {
14	  readonly issues: ValidationIssue[] = [];
15	
16	  constructor(private readonly source: JsonObject, private readonly prefix = "") {}
17	
18	  string(key: string): string {
19	    const value = this.source[key];
20	    if (typeof value !== "string") {
21	      this.fail(key, "must be a string");
22	      return "";
23	    }
24	    return value;
25	  }
26	
27	  optionalString(key: string): string | undefined {
28	    const value = this.source[key];
29	    if (value === undefined || value === null) {
30	      return undefined;
31	    }
32	    if (typeof value !== "string") {
33	      this.fail(key, "must be a string");
34	      return undefined;
35	    }
36	    return value;
37	  }
38	
39	  /** Reads a JSON number. Whether it is a valid integer or amount is decided by the core. */
40	  number(key: string): number {
41	    const value = this.source[key];
42	    if (typeof value !== "number" || !Number.isFinite(value)) {
43	      this.fail(key, "must be a number");
44	      return Number.NaN;
45	    }
46	    return value;
47	  }
48	
49	  array(key: string): unknown[] {
50	    const value = this.source[key];
51	    if (!Array.isArray(value)) {
52	      this.fail(key, "must be an array");
53	      return [];
54	    }
55	    return value;
56	  }
57	
58	  object(key: string, value: unknown): InputReader | undefined {
59	    if (!isJsonObject(value)) {
60	      this.fail(key, "must be an object");
61	      return undefined;
62	    }
63	    return new InputReader(value, this.pathOf(key));
64	  }
65	
66	  fail(key: string, message: string): void {
67	    this.issues.push({ path: this.pathOf(key), message });
68	  }
69	
70	  private pathOf(key: string): string {
71	    return this.prefix === "" ? key : `${this.prefix}.${key}`;
72	  }
73	}
